-- Generated by ergasterion/emit.py from declarations/*.yml. Do not edit by hand.
with source as (
    select * from {{ ref('stg_chrono_funds') }}
),

fund_resolution as (
    select * from {{ ref('res_fund') }}
),

gp_resolution as (
    select * from {{ ref('res_gp') }}
)

select
    source.source_system as source_system,
    source.source_record_id as source_record_id,
    source.source_fund_id as source_fund_id,
    source.source_gp_id as source_gp_id,
    source.fund_name as fund_name,
    source.fund_family_name as fund_family_name,
    source.vehicle_type as vehicle_type,
    source.gp_name as gp_name,
    source.lei as lei,
    source.shared_external_id as shared_external_id,
    source.asset_class as asset_class,
    source.strategy as strategy,
    source.vintage_year as vintage_year,
    source.committed_capital_usd as committed_capital_usd,
    source.currency as currency,
    source.domicile as domicile,
    source.fund_status as fund_status,
    source.as_of_date as as_of_date,
    source.as_of_date as effective_from,
    fund_resolution.golden_fund_key as golden_fund_key,
    fund_resolution.resolution_tier as fund_resolution_tier,
    fund_resolution.confidence as fund_resolution_confidence,
    gp_resolution.golden_gp_key as golden_gp_key,
    gp_resolution.resolution_tier as gp_resolution_tier,
    gp_resolution.confidence as gp_resolution_confidence
from source
inner join fund_resolution
    on fund_resolution.source_system = source.source_system
    and fund_resolution.source_id = source.source_fund_id
    and fund_resolution.source_record_id = source.source_record_id
left join gp_resolution
    on gp_resolution.source_system = source.source_system
    and gp_resolution.source_id = source.source_gp_id
where fund_resolution.golden_fund_key is not null
